// Dijkstra's Core Invariant: Greedy exploration of minimum distance
function dijkstra(graph, start) {
  const dist = { [start]: 0 };
  const pq = new PriorityQueue(); // O(log V) extract min
  pq.push(start, 0);
  while (!pq.isEmpty()) {
    const u = pq.pop();
    for (const [v, weight] of graph.neighbors(u)) {
      if (dist[u] + weight < (dist[v] ?? Infinity)) {
        dist[v] = dist[u] + weight;
        pq.push(v, dist[v]);
      }
    }
  }
  return dist;
}
